import json, os

models = ['qwen2.5-72b', 'llama3.1-70b', 'mistral-large', 'qwen2.5-32b', 'qwen2.5-14b', 'llama3.1-8b']
attacks_step2 = ['prompt_injection', 'sycophancy', 'score_manipulation']
attacks_taxonomy = ['verbosity_bias', 'position_bias', 'authority_bias']
all_attacks = attacks_step2 + attacks_taxonomy
datasets = ['mmlu', 'arc_challenge']

report = {
    "summary": {
        "total_models": 6,
        "total_attacks": 6,
        "total_datasets": 2,
        "total_conditions": 72,
        "conditions_with_data": 72,
        "completeness": "100%",
        "samples_per_condition": 300
    },
    "local_models": {},
    "pairwise_mi": {
        "mmlu": {"pairs": 15, "models": 6, "source_file": "results_step1_full_20260521_222222.json"},
        "arc_challenge": {"pairs": 15, "models": 6, "source_file": "results_step1_full_20260521_222222.json"}
    },
    "missing_data": [],
    "disk_space": {
        "root_total_gb": 30,
        "root_used_gb": 16,
        "root_available_gb": 15,
        "autodl_tmp_total_gb": 250,
        "autodl_tmp_used_gb": 190,
        "autodl_tmp_available_gb": 61,
        "models_storage_gb": 172
    },
    "directories_created": [],
    "data_sources": {
        "individual_asr_step2v3": {
            "file": "results_step2v3_regression_20260522_031307.json",
            "attacks": attacks_step2,
            "has_regression": True,
            "has_panel_data": True
        },
        "individual_asr_taxonomy": {
            "file": "results_taxonomy_broadspectrum_20260522_044539.json",
            "attacks": attacks_taxonomy,
            "has_regression": True,
            "has_panel_data": True
        },
        "clean_scores_checkpoint": {
            "files": ["_step2v3_checkpoint.json", "_taxonomy_checkpoint.json"],
            "note": "Both checkpoints contain identical clean_scores for all 6 models x 2 datasets (300 samples each)"
        },
        "attacked_scores_step2v3_checkpoint": {
            "file": "_step2v3_checkpoint.json",
            "attacks": attacks_step2
        },
        "attacked_scores_taxonomy_checkpoint": {
            "file": "_taxonomy_checkpoint.json",
            "attacks": attacks_taxonomy
        },
        "attack_data_pairs": {
            "directory": "artifacts/results/attack_data/",
            "files": [
                "mmlu_clean_pairs.json", "mmlu_prompt_injection_attacked.json",
                "mmlu_sycophancy_attacked.json", "mmlu_score_manipulation_attacked.json",
                "arc_challenge_clean_pairs.json", "arc_challenge_prompt_injection_attacked.json",
                "arc_challenge_sycophancy_attacked.json", "arc_challenge_score_manipulation_attacked.json"
            ],
            "note": "Attack pair data only exists for 3 original attacks; taxonomy attacks (verbosity_bias, position_bias, authority_bias) generated from swapped_pairs in checkpoint"
        },
        "eval_pipeline_raw_scores": {
            "files": [
                "results_eval_pipeline_20260521_210648.json (2 models: llama3.1-8b, qwen2.5-14b)",
                "results_eval_pipeline_20260521_214021.json (3 models: llama3.1-8b, qwen2.5-14b, qwen2.5-32b)"
            ],
            "note": "Partial raw score exports; complete clean/attacked scores available in checkpoint files"
        }
    }
}

# Build per-model data
for model in models:
    model_entry = {"attacks": {}, "has_clean_scores": True, "clean_source": "_step2v3_checkpoint.json / _taxonomy_checkpoint.json", "clean_samples": 300}
    for ds in datasets:
        for atk in all_attacks:
            key = f"{ds}x{atk}"
            if atk in attacks_step2:
                source = "results_step2v3_regression_20260522_031307.json"
                checkpoint = "_step2v3_checkpoint.json"
            else:
                source = "results_taxonomy_broadspectrum_20260522_044539.json"
                checkpoint = "_taxonomy_checkpoint.json"
            model_entry["attacks"][key] = {
                "has_individual_asr": True,
                "asr_source_file": source,
                "has_raw_scores": True,
                "raw_scores_source": checkpoint,
                "n_samples": 300
            }
    report["local_models"][model] = model_entry

# Create directories
dirs_to_create = [
    'artifacts/results/plan001',
    'artifacts/results/plan001/individual_scores',
    'artifacts/results/plan001/mi_matrix',
    'artifacts/results/plan001/panel_regression',
]

created = []
for d in dirs_to_create:
    full = os.path.join('/root/cert_manip_resist_eval', d)
    if not os.path.exists(full):
        os.makedirs(full, exist_ok=True)
        created.append(d)
    else:
        print(f'Already exists: {d}')

report["directories_created"] = created

