with open(out_path, 'w') as f:
    json.dump(report, f, indent=2)

print(f'Report written to {out_path}')
print(f'Directories created: {created}')
print(f'\nData completeness: {report["summary"]["completeness"]}')
print(f'Total conditions: {report["summary"]["total_conditions"]}')
print(f'Conditions with data: {report["summary"]["conditions_with_data"]}')
print(f'Missing data: {report["missing_data"]}')
